-- A trigger calls an extension function without its schema, as Supabase allows: there
-- `extensions` is on every connection's search path, PostgREST's included.
create table public.invites (
  id bigint generated by default as identity primary key,
  email text not null,
  token text
);
create function public.set_token() returns trigger language plpgsql as $$
begin
  new.token := encode(gen_random_bytes(8), 'hex');
  new.email := lower(new.email) || '-' || uuid_generate_v4();
  return new;
end $$;
create trigger invites_token before insert on public.invites
  for each row execute function public.set_token();
alter table public.invites enable row level security;
create policy "Anyone can ask for an invite." on public.invites
  for insert to anon with check (true);
